# Import required libraries
import chess

# Initialize board
board = chess.Board()

# Play Game of Life for 3 rounds
for _ in range(3):
    # Print current board
    print(board)

    # Make moves in Game of Life
    while True:
        try:
            move = input("Enter move (row col): ")
            row, col = map(int, move.split())
            if row < 0 or row >= 8 or col < 0 or col >= 8:
                print("Invalid move. Please try again.")
            else:
                board.push(chess.Move(row, col))
                break
        except ValueError:
            print("Invalid input. Please try again.")

# Play chess
chess.play({
    "moves": ["e4", "e5"],
    "rounds": 1
}, {
    "start_board": board
})
```

This script first initializes a chess board and then plays a game of life for 3 rounds. It then makes the first move of the game of life (e4) and the second move (e5) in chess. The script continues to prompt the user for moves until the game of life is over. Finally, it plays the game of life with the first move (e4) and the second move (e5) in chess.

