import requests

def fetch_top_artworks(metropolitan_museum):
    params = {
        "number": 10,
        "sort_by": "popularity"
    }
    response = requests.get(f"{metropolitan_museum.get_api_url()}/top_artworks", params=params)
    return response.json()

def fetch_top_artworks_sorted_by_popularity(metropolitan_museum):
    top_artworks = fetch_top_artworks(metropolitan_museum)
    return top_artworks

def fetch_top_artworks_sorted_bychronological(metropolitan_museum):
    top_artworks = fetch_top_artworks(metropolitan_museum)
    return sorted(top_artworks, key=lambda x: x['date'], reverse=True)

def search_lawsuit(start_date, location, status):
    url = f"https://www.google.com/search?q=lawsuit+{status}+{location}+from+{start_date}"
    response = requests.get(url)
    return response.json()

def search_lawsuit_ongoing():
    url = "https://www.google.com/search?q=lawsuit+ongoing+california+from+2020"
    response = requests.get(url)
    return response.json()

def search_lawsuit_settled():
    url = "https://www.google.com/search?q=lawsuit+settled+new+york+from+2018"
    response = requests.get(url)
    return response.json()

# Usage
metropolitan_museum = {
    "get_top_artworks": fetch_top_artworks,
    "get_top_artworks_sorted_by_popularity": fetch_top_artworks_sorted_by_popularity,
    "get_top_artworks_sorted_bychronological": fetch_top_artworks_sorted_bychronological
}

